def _as_utc(value):
    """Return an aware UTC datetime, treating naive values as UTC."""
    if value.tzinfo is None or value.utcoffset() is None:
        return value.replace(tzinfo=UTC)
    return value.astimezone(UTC)


def stamp():
    return datetime.now(UTC).strftime(STAMP_FORMAT)


def record(log, actor, action, when=None):
    when = datetime.now(UTC) if when is None else _as_utc(when)
    entry = {"at": when.strftime(STAMP_FORMAT), "actor": actor, "action": action}
    log.append(entry)
    return entry


def parse_stamp(text):
    return datetime.strptime(text, STAMP_FORMAT).replace(tzinfo=UTC)


def since(log, cutoff):
    cutoff = _as_utc(cutoff)
    return [e for e in log if parse_stamp(e["at"]) >= cutoff]
